// File: arb_scoreboard.sv
// Scoreboard with reference model for round-robin arbiter

class arb_scoreboard #(parameter int N = 4) extends uvm_scoreboard;

    `uvm_component_param_utils(arb_scoreboard#(N))

    uvm_analysis_imp #(arb_seq_item#(N), arb_scoreboard#(N)) analysis_export;

    // Reference model state
    logic [N-1:0] ref_priority_ptr;
    int unsigned   pass_count;
    int unsigned   fail_count;
    int unsigned   txn_count;
    bit            first_active;  // Flag: first transaction after reset

    function new(string name = "arb_scoreboard", uvm_component parent = null);
        super.new(name, parent);
        ref_priority_ptr = {{(N-1){1'b0}}, 1'b1};
        pass_count = 0;
        fail_count = 0;
        txn_count  = 0;
        first_active = 0;
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        analysis_export = new("analysis_export", this);
    endfunction

    // Reference model: compute expected grant given req and priority_ptr
    function logic [N-1:0] compute_expected_grant(
        input logic [N-1:0] req,
        input logic [N-1:0] ptr
    );
        logic [N-1:0] mask_val;
        logic [N-1:0] masked_req_val;
        logic [N-1:0] masked_grant_val;
        logic [N-1:0] raw_grant_val;

        // Compute mask from priority pointer
        mask_val = ~(ptr - 1'b1);

        // Masked request
        masked_req_val = req & mask_val;

        // Lowest bit of masked request
        masked_grant_val = masked_req_val & (~masked_req_val + 1'b1);

        // Lowest bit of raw request (fallback)
        raw_grant_val = req & (~req + 1'b1);

        if (|masked_req_val)
            return masked_grant_val;
        else
            return raw_grant_val;
    endfunction

    // Update reference priority pointer after grant
    function void update_ref_ptr(input logic [N-1:0] grant);
        if (|grant)
            ref_priority_ptr = {grant[N-2:0], grant[N-1]};
        // else: hold
    endfunction

    // Analysis port write function
    function void write(arb_seq_item#(N) txn);
        logic [N-1:0] expected_grant;

        txn_count++;

        // Handle reset
        if (!txn.rst_n) begin
            ref_priority_ptr = {{(N-1){1'b0}}, 1'b1};
            first_active = 1;
            `uvm_info(get_type_name(), "Reset detected - reference model reset", UVM_HIGH)
            return;
        end

        // Skip first cycle after reset to allow model synchronization
        if (first_active) begin
            first_active = 0;
            // Re-sync: compute expected with reset ptr
            expected_grant = compute_expected_grant(txn.req, ref_priority_ptr);
            if (txn.grant !== expected_grant) begin
                `uvm_info(get_type_name(),
                    $sformatf("First-cycle sync: grant=%0b expected=%0b req=%0b ptr=%0b",
                              txn.grant, expected_grant, txn.req, ref_priority_ptr), UVM_HIGH)
            end
            // Update pointer based on actual grant to stay in sync
            update_ref_ptr(txn.grant);
            return;
        end

        // Compute expected grant
        expected_grant = compute_expected_grant(txn.req, ref_priority_ptr);

        if (txn.grant !== expected_grant) begin
            `uvm_error(get_type_name(),
                $sformatf("MISMATCH [txn#%0d]: req=%b grant=%b expected=%b ref_ptr=%b",
                          txn_count, txn.req, txn.grant, expected_grant, ref_priority_ptr))
            fail_count++;
        end else begin
            `uvm_info(get_type_name(),
                $sformatf("MATCH [txn#%0d]: req=%b grant=%b ptr=%b",
                          txn_count, txn.req, txn.grant, ref_priority_ptr), UVM_HIGH)
            pass_count++;
        end

        // Update reference model state
        update_ref_ptr(txn.grant);

    endfunction

    function void report_phase(uvm_phase phase);
        super.report_phase(phase);
        `uvm_info(get_type_name(),
            $sformatf("\n========== Scoreboard Summary ==========\n  Total Transactions: %0d\n  Pass: %0d\n  Fail: %0d\n=========================================",
                      txn_count, pass_count, fail_count), UVM_LOW)
        if (fail_count > 0)
            `uvm_error(get_type_name(), $sformatf("%0d transactions FAILED!", fail_count))
        else
            `uvm_info(get_type_name(), "All transactions PASSED!", UVM_LOW)
    endfunction

endclass

