// File: arb_coverage.sv
// Functional coverage subscriber for round-robin arbiter

class arb_coverage #(parameter int N = 4) extends uvm_subscriber #(arb_seq_item#(N));

    `uvm_component_param_utils(arb_coverage#(N))

    // Stored transaction fields for covergroup sampling
    logic [N-1:0] req;
    logic [N-1:0] grant;
    logic         rst_n;
    logic [N-1:0] prev_grant;
    bit           has_prev;

    // Covergroup definition
    covergroup cg_arb;
        option.per_instance = 1;
        option.name = "arb_coverage_cg";

        // Request patterns
        cp_req: coverpoint req {
            bins no_req      = {0};
            bins all_req     = {{N{1'b1}}};
            bins single_req[N] = {[0:$]} iff ($countones(req) == 1);
            bins multi_req   = {[1:$]} iff ($countones(req) > 1 && req != {N{1'b1}});
        }

        // Grant patterns
        cp_grant: coverpoint grant {
            bins no_grant    = {0};
            bins grant_port[N] = {[0:$]} iff ($countones(grant) == 1);
        }

        // Individual request bits
        cp_req_bit0: coverpoint req[0];
        cp_req_bit1: coverpoint req[1];
        cp_req_bit2: coverpoint req[2];
        cp_req_bit3: coverpoint req[3];

        // Individual grant bits
        cp_grant_bit0: coverpoint grant[0];
        cp_grant_bit1: coverpoint grant[1];
        cp_grant_bit2: coverpoint grant[2];
        cp_grant_bit3: coverpoint grant[3];

        // Grant is subset of request
        cp_grant_valid: coverpoint ((grant & ~req) == '0) {
            bins valid   = {1};
        }

        // Cross coverage: request vs grant
        cx_req_grant: cross cp_req, cp_grant;

        // Reset state
        cp_rst_n: coverpoint rst_n {
            bins active = {1};
            bins reset  = {0};
        }

        // Transitions: consecutive grant ports (round-robin behavior)
        cp_grant_transitions: coverpoint grant {
            bins g0_to_g1 = (4'b0001 => 4'b0010);
            bins g1_to_g2 = (4'b0010 => 4'b0100);
            bins g2_to_g3 = (4'b0100 => 4'b1000);
            bins g3_to_g0 = (4'b1000 => 4'b0001);
            bins g_to_none = (4'b0001, 4'b0010, 4'b0100, 4'b1000 => 4'b0000);
            bins none_to_g = (4'b0000 => 4'b0001, 4'b0010, 4'b0100, 4'b1000);
        }

    endgroup

    // Covergroup for specific scenarios targeted by SVA
    covergroup cg_sva_scenarios;
        option.per_instance = 1;
        option.name = "sva_scenario_cg";

        // No request scenario
        cp_no_req_no_grant: coverpoint (req == '0 && grant == '0) {
            bins hit = {1};
        }

        // Wrap-around scenario: grant at lowest bit when no masked requests
        cp_wrap_around: coverpoint (grant != '0 && (grant < prev_grant || !has_prev)) iff (rst_n) {
            bins wrap = {1};
        }

        // All requesting with grant rotating
        cp_all_req: coverpoint (req == {N{1'b1}}) iff (rst_n) {
            bins all_requesting = {1};
        }

    endgroup

    function new(string name = "arb_coverage", uvm_component parent = null);
        super.new(name, parent);
        cg_arb = new();
        cg_sva_scenarios = new();
        has_prev = 0;
    endfunction

    // Called by analysis port write
    function void write(arb_seq_item#(N) t);
        req   = t.req;
        grant = t.grant;
        rst_n = t.rst_n;

        cg_arb.sample();
        cg_sva_scenarios.sample();

        prev_grant = grant;
        has_prev = 1;
    endfunction

    function void report_phase(uvm_phase phase);
        super.report_phase(phase);
        `uvm_info(get_type_name(),
            $sformatf("\n========== Coverage Summary ==========\n  cg_arb:           %.2f%%\n  cg_sva_scenarios: %.2f%%\n=======================================",
                      cg_arb.get_inst_coverage(), cg_sva_scenarios.get_inst_coverage()), UVM_LOW)
    endfunction

endclass

