// File: arb_agent.sv
// Agent: bundles driver, sequencer, and monitor

class arb_agent #(parameter int N = 4) extends uvm_agent;

    `uvm_component_param_utils(arb_agent#(N))

    arb_driver    #(N) drv;
    arb_sequencer #(N) sqr;
    arb_monitor   #(N) mon;

    function new(string name = "arb_agent", uvm_component parent = null);
        super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);

        // Always create monitor
        mon = arb_monitor#(N)::type_id::create("mon", this);

        // Create driver and sequencer only in ACTIVE mode
        if (get_is_active() == UVM_ACTIVE) begin
            drv = arb_driver#(N)::type_id::create("drv", this);
            sqr = arb_sequencer#(N)::type_id::create("sqr", this);
        end
    endfunction

    function void connect_phase(uvm_phase phase);
        super.connect_phase(phase);

        // Connect driver to sequencer in ACTIVE mode
        if (get_is_active() == UVM_ACTIVE) begin
            drv.seq_item_port.connect(sqr.seq_item_export);
        end
    endfunction

endclass

