        env = arb_env#(N)::type_id::create("env", this);
    endfunction

    virtual task run_phase(uvm_phase phase);
        arb_full_seq #(N) full_seq;

        phase.raise_objection(this, "Starting test");

        full_seq = arb_full_seq#(N)::type_id::create("full_seq");
        full_seq.start(env.agent.sqr);

        // Allow drain time for remaining transactions
        #100;

        phase.drop_objection(this, "Test complete");
    endtask

    function void report_phase(uvm_phase phase);
        uvm_report_server svr;
        super.report_phase(phase);
        svr = uvm_report_server::get_server();
        if (svr.get_severity_count(UVM_ERROR) == 0 &&
            svr.get_severity_count(UVM_FATAL) == 0)
            `uvm_info(get_type_name(), "\n*** TEST PASSED ***", UVM_NONE)
        else
            `uvm_error(get_type_name(), "\n*** TEST FAILED ***")
    endfunction

endclass

// Non-parameterized wrapper for run_test() lookup
class arb_base_test extends arb_test #(4);
    `uvm_component_utils(arb_base_test)

    function new(string name = "arb_base_test", uvm_component parent = null);
        super.new(name, parent);
    endfunction
endclass

// ════════════════════════════════════════════════════════════
// UVM Top (tb_top)
// ════════════════════════════════════════════════════════════

// File: tb_top.sv
// Top-level testbench module

module tb_top;

    // Parameters
    localparam int N = 4;

    // Clock generation
    logic clk;
    initial begin
        clk = 0;
        forever #5 clk = ~clk;  // 100 MHz clock, 10ns period
    end

    // Interface instantiation (uses existing arb_if from design file)
    arb_if #(.N(N)) vif (.clk(clk));

    // DUT instantiation
    round_robin_arbiter #(.N(N)) dut (
        .clk    (clk),
        .rst_n  (vif.rst_n),
        .req    (vif.req),
        .grant  (vif.grant)
    );

    // Reset generation
    initial begin
        vif.rst_n = 1'b0;
        vif.req   = '0;
        repeat (5) @(posedge clk);
        vif.rst_n = 1'b1;
    end

    // Store virtual interface in config_db for UVM components
    initial begin
        uvm_config_db#(virtual arb_if#(N))::set(null, "uvm_test_top.env.agent.*", "vif", vif);
        uvm_config_db#(virtual arb_if#(N))::set(null, "uvm_test_top.env.agent.drv", "vif", vif);
        uvm_config_db#(virtual arb_if#(N))::set(null, "uvm_test_top.env.agent.mon", "vif", vif);
    end

    // Start UVM test
    initial begin
        run_test("arb_base_test");
    end

    // Simulation timeout and waveform dump
    initial begin
        $timeformat(-9, 0, " ns", 12);
        #100_000;
        `uvm_fatal("TIMEOUT", "Simulation timed out!")
    end

    // Optional: waveform dump
    initial begin
        $dumpfile("dump.vcd");
        $dumpvars(0, tb_top);
    end

endmodule

